diff -ruN '--exclude=node_modules' '--exclude=.git' a/csv.test.ts b/csv.test.ts
--- a/csv.test.ts	2026-10-28 09:22:36.548009473 +0000
+++ b/csv.test.ts	2026-10-28 09:23:25.799159733 +0000
@@ -23,3 +23,105 @@
   expect(s.push("d")).toEqual([]);
   expect(s.end()).toEqual([["c", "d"]]);
 });
+
+/** Runs `chunks` through a CsvStream and returns all rows, or the error it threw. */
+function streamAll(chunks: string[]): string[][] | Error {
+  const s = new CsvStream();
+  const rows: string[][] = [];
+  try {
+    for (const chunk of chunks) rows.push(...s.push(chunk));
+    rows.push(...s.end());
+    return rows;
+  } catch (e) {
+    return e as Error;
+  }
+}
+
+function expectSameAsParseCsv(text: string, chunks: string[]) {
+  let expected: string[][] | undefined;
+  try {
+    expected = parseCsv(text);
+  } catch (e) {
+    expect(e).toBeInstanceOf(SyntaxError);
+  }
+  const got = streamAll(chunks);
+  if (expected === undefined) expect(got).toBeInstanceOf(SyntaxError);
+  else expect(got).toEqual(expected);
+}
+
+test("a row end split between chunks", () => {
+  const s = new CsvStream();
+  expect(s.push("a\r")).toEqual([]);
+  expect(s.push("\nb")).toEqual([["a"]]);
+  expect(s.end()).toEqual([["b"]]);
+  expect(streamAll(["a\r", "b"])).toEqual([["a\rb"]]);
+  expect(streamAll(["a\r"])).toEqual([["a\r"]]);
+  expect(streamAll(["a\r", "\r", "\n"])).toEqual([["a\r"]]);
+});
+
+test("a doubled or closing quote split between chunks", () => {
+  expect(streamAll(['"a"', '"b"'])).toEqual([['a"b']]);
+  expect(streamAll(['"a"', ",b"])).toEqual([["a", "b"]]);
+  expect(streamAll(['"a"'])).toEqual([["a"]]);
+  expect(streamAll(['"a"', "\r", "\n"])).toEqual([["a"]]);
+});
+
+test("a row end before the end of the input does not start another row", () => {
+  expect(streamAll(["a\n"])).toEqual([["a"]]);
+  expect(streamAll(["a\n", ""])).toEqual([["a"]]);
+  expect(streamAll(["\n"])).toEqual([[""]]);
+  expect(streamAll(["a,"])).toEqual([["a", ""]]);
+  expect(streamAll([])).toEqual([]);
+  expect(streamAll(["", ""])).toEqual([]);
+});
+
+test("a BOM is dropped only at the very start of the input", () => {
+  expect(streamAll(["", "\uFEFFa"])).toEqual([["a"]]);
+  expect(streamAll(["\uFEFF"])).toEqual([]);
+  expect(streamAll(["a", "\uFEFFb"])).toEqual([["a\uFEFFb"]]);
+  expect(streamAll(["\uFEFF", "\uFEFFb"])).toEqual([["\uFEFFb"]]);
+});
+
+test("rejected inputs throw a SyntaxError from push or end", () => {
+  for (const chunks of [['"a"b'], ['"a"', "b"], ['"a'], ['"a"', "\r"], ['"a"\r', "x"], ["a", '"'], ['"a""']]) {
+    expect(streamAll(chunks)).toBeInstanceOf(SyntaxError);
+  }
+});
+
+test("every input over a small alphabet, split every way, matches parseCsv", () => {
+  const alphabet = ["a", ",", '"', "\r", "\n", "\uFEFF"];
+  const inputs = [""];
+  for (let len = 1; len <= 5; len++) {
+    for (const prev of inputs.filter((s) => s.length === len - 1)) for (const c of alphabet) inputs.push(prev + c);
+  }
+  for (const text of inputs) {
+    // every way of cutting the text into chunks, one bit per gap between characters
+    for (let cuts = 0; cuts < 1 << Math.max(0, text.length - 1); cuts++) {
+      const chunks: string[] = [];
+      let start = 0;
+      for (let i = 1; i < text.length; i++) {
+        if (cuts & (1 << (i - 1))) {
+          chunks.push(text.slice(start, i));
+          start = i;
+        }
+      }
+      chunks.push(text.slice(start));
+      expectSameAsParseCsv(text, chunks);
+    }
+  }
+});
+
+test("the work for a chunk does not grow with the input before it", () => {
+  const s = new CsvStream();
+  const line = '"x,""y""",z\r\n';
+  const time = (n: number) => {
+    const t = performance.now();
+    for (let k = 0; k < n; k++) s.push(line);
+    return performance.now() - t;
+  };
+  time(20000);
+  const first = time(20000);
+  for (let k = 0; k < 20; k++) time(20000);
+  expect(time(20000)).toBeLessThan(first * 5 + 50);
+  s.end();
+});
diff -ruN '--exclude=node_modules' '--exclude=.git' a/csv.ts b/csv.ts
--- a/csv.ts	2026-10-28 09:22:36.548042290 +0000
+++ b/csv.ts	2026-10-28 09:23:05.703158538 +0000
@@ -50,3 +50,127 @@
   rows.push(row);
   return rows;
 }
+
+const enum State {
+  FieldStart, // at the start of a field
+  Unquoted, // inside a field that is not quoted
+  UnquotedCr, // a `\r` in a field that is not quoted, waiting to see whether `\n` follows
+  Quoted, // inside a quoted field
+  QuotedQuote, // a `"` inside a quoted field, waiting to see whether it is doubled
+  Closed, // after the closing quote of a field
+  ClosedCr, // a `\r` after a closing quote, which must be followed by `\n`
+}
+
+/**
+ * Reads CSV as `parseCsv` does, from chunks split anywhere. Each `push` returns the rows whose row end has arrived,
+ * and `end` returns the rest; together they equal `parseCsv` of the whole input, and an input it rejects makes a
+ * `push` or `end` throw a SyntaxError. The work for a chunk depends only on the chunk.
+ */
+export class CsvStream {
+  private state = State.FieldStart;
+  private row: string[] = [];
+  private rowOpen = false; // whether the current row has begun
+  private field = "";
+  private offset = 0; // offset in the whole input of the next character
+  private ended = false;
+
+  push(chunk: string): string[][] {
+    if (this.ended) throw new Error("push after end");
+    const rows: string[][] = [];
+    let i = 0;
+    if (this.offset === 0 && chunk.startsWith("﻿")) {
+      i = 1;
+    }
+    for (; i < chunk.length; i++) {
+      const c = chunk[i]!;
+      const at = this.offset + i;
+      switch (this.state) {
+        case State.FieldStart:
+          this.rowOpen = true;
+          if (c === '"') this.state = State.Quoted;
+          else this.unquoted(c, at, rows);
+          break;
+        case State.Unquoted:
+          this.unquoted(c, at, rows);
+          break;
+        case State.UnquotedCr:
+          if (c === "\n") this.endRow(rows);
+          else {
+            this.field += "\r";
+            this.unquoted(c, at, rows);
+          }
+          break;
+        case State.Quoted:
+          if (c === '"') this.state = State.QuotedQuote;
+          else this.field += c;
+          break;
+        case State.QuotedQuote:
+          if (c === '"') {
+            this.field += '"';
+            this.state = State.Quoted;
+          } else {
+            this.state = State.Closed;
+            this.closed(c, at, rows);
+          }
+          break;
+        case State.Closed:
+          this.closed(c, at, rows);
+          break;
+        case State.ClosedCr:
+          if (c !== "\n") throw new SyntaxError(`unexpected "\\r" after a closing quote at offset ${at - 1}`);
+          this.endRow(rows);
+          break;
+      }
+    }
+    this.offset += chunk.length;
+    return rows;
+  }
+
+  end(): string[][] {
+    if (this.ended) throw new Error("end called twice");
+    this.ended = true;
+    switch (this.state) {
+      case State.Quoted:
+        throw new SyntaxError("a quoted field is still open at the end of the input");
+      case State.ClosedCr:
+        throw new SyntaxError(`unexpected "\\r" after a closing quote at offset ${this.offset - 1}`);
+      case State.UnquotedCr:
+        this.field += "\r";
+        break;
+    }
+    if (!this.rowOpen) return [];
+    this.row.push(this.field);
+    return [this.row];
+  }
+
+  private unquoted(c: string, at: number, rows: string[][]): void {
+    if (c === ",") this.endField();
+    else if (c === "\n") this.endRow(rows);
+    else if (c === "\r") this.state = State.UnquotedCr;
+    else if (c === '"') throw new SyntaxError(`a quote in a field that is not quoted, at offset ${at}`);
+    else {
+      this.field += c;
+      this.state = State.Unquoted;
+    }
+  }
+
+  private closed(c: string, at: number, rows: string[][]): void {
+    if (c === ",") this.endField();
+    else if (c === "\n") this.endRow(rows);
+    else if (c === "\r") this.state = State.ClosedCr;
+    else throw new SyntaxError(`unexpected ${JSON.stringify(c)} after a closing quote at offset ${at}`);
+  }
+
+  private endField(): void {
+    this.row.push(this.field);
+    this.field = "";
+    this.state = State.FieldStart;
+  }
+
+  private endRow(rows: string[][]): void {
+    this.endField();
+    rows.push(this.row);
+    this.row = [];
+    this.rowOpen = false;
+  }
+}

