+  if (cmd === 'rm') return rmHit(argv.slice(1), cwd);
+  if (cmd === 'find') return findHit(argv.slice(1), cwd);
+  return undefined;
+}
+
+// A short flag group such as -f or -fdx (not --long, not a lone -).
+const shortGroupHas = (word: string, letters: string) =>
+  /^-[^-]/.test(word) && [...word.slice(1)].some((c) => letters.includes(c));
+
+const longFlag = (word: string, names: string[]) => names.some((n) => word === n || word.startsWith(n + '='));
+
+// $VAR or ~user cannot be resolved before the command runs.
+const unresolvable = (path: string) => path.includes('$') || (path.startsWith('~') && path !== '~' && !path.startsWith('~/'));
+
+const outside = (path: string, cwd: string) => unresolvable(path) || !insideWorkspace(path, cwd);
+
+const valueOptions = ['-C', '-c', '--git-dir', '--work-tree', '--namespace'];
+
+function gitHit(args: string[]): Hit | undefined {
+  let i = 0;
+  while (i < args.length && args[i].startsWith('-')) i += valueOptions.includes(args[i]) ? 2 : 1;
+  const sub = args[i];
+  const rest = args.slice(i + 1);
+  if (sub === 'push') {
+    const force = rest.some(
+      (w) =>
+        longFlag(w, ['--force', '--force-with-lease', '--mirror', '--delete', '--prune']) ||
+        shortGroupHas(w, 'fd') ||
+        w.startsWith('+') ||
+        w.startsWith(':'),
+    );
+    if (force) return { name: 'force-push', reason: 'git push that rewrites or deletes remote refs' };
+  } else if (sub === 'reset') {
+    if (rest.includes('--hard')) return { name: 'reset-hard', reason: 'git reset --hard discards local changes' };
+  } else if (sub === 'clean') {
+    const force = rest.some((w) => w === '--force' || shortGroupHas(w, 'f'));
+    const dryRun = rest.includes('-n') || rest.includes('--dry-run');
+    if (force && !dryRun) return { name: 'clean-force', reason: 'git clean -f deletes untracked files' };
+  }
+  return undefined;
+}
+
+function rmHit(args: string[], cwd: string): Hit | undefined {
+  const dashes = args.indexOf('--');
+  const before = dashes === -1 ? args : args.slice(0, dashes);
+  const after = dashes === -1 ? [] : args.slice(dashes + 1);
+  const flags = before.filter((w) => w.startsWith('-'));
+  const targets = [...before.filter((w) => !w.startsWith('-')), ...after];
+  if (!flags.some((w) => w === '--recursive' || shortGroupHas(w, 'rR'))) return undefined;
+  if (targets.length === 0) return { name: 'rm-outside', reason: 'recursive rm with no visible targets' };
+  const bad = targets.find((t) => outside(t, cwd) || sameDir(t, cwd));
+  if (bad !== undefined) return { name: 'rm-outside', reason: `recursive rm of ${bad}, outside the working directory or the directory itself` };
+  return undefined;
+}
+
+function findHit(args: string[], cwd: string): Hit | undefined {
+  if (!args.some((w) => w === '-delete' || w === '-exec' || w === '-execdir')) return undefined;
+  const first = args.findIndex((w) => w.startsWith('-'));
+  const starts = first === -1 ? args : args.slice(0, first);
+  const bad = (starts.length ? starts : ['.']).find((p) => outside(p, cwd));
+  if (bad !== undefined) return { name: 'rm-outside', reason: `find that deletes or runs commands under ${bad}, outside the working directory` };
+  return undefined;
 }

