+    ['trailing-space', (l) => l.trimEnd()],
+    ['indentation', (l) => l.trim()],
+  ];
+  for (const [tier, norm] of tiers) {
+    const want = oldLines.map(norm);
+    const starts: number[] = [];
+    for (let s = 0; s + want.length <= lines.length; s++) {
+      if (want.every((w, k) => norm(lines[s + k]) === w)) starts.push(s);
+    }
+    if (starts.length > 1) {
+      return { error: `old_text matches ${starts.length} places (${tier} match), at lines ${starts.map((s) => s + 1).join(', ')}; add surrounding lines to make it unique` };
+    }
+    if (starts.length === 1) {
+      const s = starts[0];
+      let replacement = newLines;
+      if (tier === 'indentation') {
