@@ -0,0 +1,68 @@
+import { expect, test } from "bun:test";
+import { distinctInWindow } from "./window";
+
+function slow(events: { t: number; key: string }[], windowMs: number): number[] {
+  return events.map((e) => {
+    const keys = new Set<string>();
+    for (const other of events) if (other.t > e.t - windowMs && other.t <= e.t) keys.add(other.key);
+    return keys.size;
+  });
+}
+
+test("events out of order count later entries with the same or earlier time", () => {
+  const events = [
+    { t: 8, key: "a" },
+    { t: 5, key: "b" },
+    { t: 8, key: "c" },
+    { t: 0, key: "a" },
+    { t: 18, key: "d" },
+  ];
+  expect(distinctInWindow(events, 10)).toEqual([3, 2, 3, 1, 1]);
+});
+
+test("the window excludes its start and includes its end", () => {
+  const events = [
+    { t: 0, key: "a" },
+    { t: 10, key: "b" },
+    { t: 10.5, key: "c" },
+  ];
+  expect(distinctInWindow(events, 10)).toEqual([1, 1, 2]);
+});
+
+test("keys are compared exactly", () => {
+  const events = [
+    { t: 1, key: "a" },
+    { t: 2, key: "A" },
+    { t: 3, key: "a " },
+    { t: 4, key: "a" },
+    { t: 5, key: "__proto__" },
+  ];
+  expect(distinctInWindow(events, 100)).toEqual([1, 2, 3, 3, 4]);
+});
+
+test("bad windows are refused with a RangeError", () => {
+  for (const w of [-1, NaN, Infinity]) expect(() => distinctInWindow([{ t: 1, key: "a" }], w)).toThrow(RangeError);
+});
+
+test("a bad time is a TypeError naming the first bad index", () => {
+  const events = [{ t: 1, key: "a" }, { t: NaN, key: "b" }, { t: "3" as unknown as number, key: "c" }];
+  expect(() => distinctInWindow(events, 10)).toThrow(new TypeError("event 1 has no finite time: NaN"));
+});
+
+test("matches the plain definition on random input", () => {
+  let seed = 7;
+  const rand = () => (seed = (seed * 1103515245 + 12345) % 2147483648) / 2147483648;
+  for (let round = 0; round < 50; round++) {
+    const events = Array.from({ length: 60 }, () => ({ t: Math.floor(rand() * 40) / 2 - 5, key: String(Math.floor(rand() * 6)) }));
+    const w = 0.5 + Math.floor(rand() * 20) / 2;
+    expect(distinctInWindow(events, w)).toEqual(slow(events, w));
+  }
+});
+
+test("200,000 events take under a second", () => {
+  const events = Array.from({ length: 200_000 }, (_, i) => ({ t: (i * 7919) % 1_000_000, key: `k${i % 5000}` }));
+  const start = performance.now();
+  const result = distinctInWindow(events, 50_000);
+  expect(performance.now() - start).toBeLessThan(1000);
+  expect(result.length).toBe(200_000);
+});
