+  expect(formatDuration(90_000)).toBe('1m30s');
+  expect(formatDuration(7)).toBe('7ms');
+  expect(() => formatDuration(-1)).toThrow();
+  for (const ms of [1, 999, 61_001, 93_784_005]) expect(parseDuration(formatDuration(ms))).toBe(ms);
